// ProductServiceHandler is an implementation of the hawkr.product.ProductService service.
type ProductServiceHandler interface {
	// 建立商品
	CreateProduct(context.Context, *connect.Request[product.CreateProductRequest]) (*connect.Response[product.CreateProductResponse], error)
	// 更新商品
	UpdateProduct(context.Context, *connect.Request[product.UpdateProductRequest]) (*connect.Response[product.UpdateProductResponse], error)
	// 取得商品詳情（含權限檢查，賣家端使用）
	GetProduct(context.Context, *connect.Request[product.GetProductRequest]) (*connect.Response[product.GetProductResponse], error)
	// 公開商品詳情（PUBLIC / TEMPORARILY_UNAVAILABLE，支援 Redis 快取）
	GetPublicProduct(context.Context, *connect.Request[product.GetPublicProductRequest]) (*connect.Response[product.GetProductResponse], error)
	// 取得商品列表（禁止 join product_sku）
	GetProductList(context.Context, *connect.Request[product.GetProductListRequest]) (*connect.Response[product.GetProductListResponse], error)
	// 管理員取得商品詳情（不檢查擁有者，不限狀態，僅限管理員）
	GetProductForAdmin(context.Context, *connect.Request[product.GetProductForAdminRequest]) (*connect.Response[product.GetProductResponse], error)
	// 管理員更新商品狀態（不檢查擁有者，僅限管理員）
	UpdateProductStatus(context.Context, *connect.Request[product.UpdateProductStatusRequest]) (*connect.Response[product.UpdateProductResponse], error)
	// 賣家更新商品狀態（含擁有者驗證 + 狀態轉換驗證）
	UpdateSellerProductStatus(context.Context, *connect.Request[product.UpdateSellerProductStatusRequest]) (*connect.Response[product.UpdateProductResponse], error)
	// 賣家批次更新商品狀態（含擁有者驗證 + 逐筆狀態轉換驗證 + 逐筆樂觀鎖）。
	// 逐項獨立成敗，禁止用單一交易包住全批 —— 一項版本衝突不得讓其他項回滾。
	BatchUpdateSellerProductStatus(context.Context, *connect.Request[product.BatchUpdateSellerProductStatusRequest]) (*connect.Response[product.BatchUpdateSellerProductStatusResponse], error)
	// 批次取 before 快照與當前 version（代行批次寫入的第一跳，56 設計書 §7.2.8 步驟 ②）。
	// 存在的理由是「跳數不得與 items 筆數成正比」：逐項打 GetProduct 會讓
	//    一次 50 筆的批次多出 50 跳，而 prod 的 account-service 連線池只有 2。
	// 唯讀；查不到的 product_id 在 results 內以 found=false 回報，不整批失敗
	//    —— 那一項的失敗要走稽核（intent → FAILED），不能在讀取階段就消失。
	BatchGetSellerProductsForDelegation(context.Context, *connect.Request[product.BatchGetSellerProductsForDelegationRequest]) (*connect.Response[product.BatchGetSellerProductsForDelegationResponse], error)
	// 清除商品快取
	PurgeProductCache(context.Context, *connect.Request[product.PurgeProductCacheRequest]) (*connect.Response[product.PurgeProductCacheResponse], error)
	// 原子扣減庫存（不可逐筆部分成功）
	DeductStock(context.Context, *connect.Request[product.DeductStockRequest]) (*connect.Response[product.StockOperationResponse], error)
	// 原子歸還庫存（補償/取消，冪等）
	RestoreStock(context.Context, *connect.Request[product.RestoreStockRequest]) (*connect.Response[product.StockOperationResponse], error)
	// 查詢庫存
	GetStock(context.Context, *connect.Request[product.GetStockRequest]) (*connect.Response[product.GetStockResponse], error)
	// 取得商品簡化資訊（驗證 SKU + 取得快照）
	GetProductSimple(context.Context, *connect.Request[product.GetProductSimpleRequest]) (*connect.Response[product.GetProductSimpleResponse], error)
	// 批次取得 SKU 即時資訊（購物車列表顯示用：庫存+溫層+價格+上架狀態）
	BatchGetSkuCartInfo(context.Context, *connect.Request[product.BatchGetSkuCartInfoRequest]) (*connect.Response[product.BatchGetSkuCartInfoResponse], error)
	// 結帳鏈路批次商品查詢（Order Service Checkout 呼叫）— **接受 inactive product 不拋例外**，
	// 回完整 weight / dimension / shipping_method 等結帳必要欄位。詳見 02 設計書 §5.5.2
	BatchGetProductForCheckout(context.Context, *connect.Request[product.BatchGetProductForCheckoutRequest]) (*connect.Response[product.BatchGetProductForCheckoutResponse], error)
	// 批次取得商品資訊（買家瀏覽紀錄使用）
	GetProductsByIDs(context.Context, *connect.Request[product.GetProductsByIDsRequest]) (*connect.Response[product.GetProductsByIDsResponse], error)
	// 取得相關商品（同分類、排除自身、僅上架、上限 8 筆）
	GetRelatedProducts(context.Context, *connect.Request[product.GetRelatedProductsRequest]) (*connect.Response[product.GetRelatedProductsResponse], error)
	// 軟刪除商品（僅限擁有者，僅草稿(4001)/未上架(4003)狀態）
	DeleteProduct(context.Context, *connect.Request[product.DeleteProductRequest]) (*connect.Response[product.DeleteProductResponse], error)
	// 計算可用配送選項與運費（依溫層分組）
	CalculateShippingOptions(context.Context, *connect.Request[product.CalculateShippingOptionsRequest]) (*connect.Response[product.CalculateShippingOptionsResponse], error)
	// 驗證認證編號是否存在於政府開放資料平台 — 僅限 Seller (account_type: 2, 3)
	VerifyCertification(context.Context, *connect.Request[product.VerifyCertificationRequest]) (*connect.Response[product.VerifyCertificationResponse], error)
	// 送出認證申請；同步階段只讀快取不發外部呼叫，命中「有效」即自動核准
	SubmitProductCertification(context.Context, *connect.Request[product.SubmitProductCertificationRequest]) (*connect.Response[product.ProductCertificationApplicationResponse], error)
	// 查詢某商品的認證申請列表（賣家視角，不含 gov_verify_payload / internal_note）
	ListProductCertificationApplications(context.Context, *connect.Request[product.ListProductCertificationApplicationsRequest]) (*connect.Response[product.ListProductCertificationApplicationsResponse], error)
	// 撤回待審申請（樂觀鎖 expected_version）
	WithdrawProductCertification(context.Context, *connect.Request[product.WithdrawProductCertificationRequest]) (*connect.Response[product.ProductCertificationApplicationResponse], error)
	// Admin 審核佇列查詢（status / type / store / keyword / 送出時間區間）
	ListProductCertificationApplicationsForAdmin(context.Context, *connect.Request[product.ListProductCertificationApplicationsForAdminRequest]) (*connect.Response[product.ListProductCertificationApplicationsForAdminResponse], error)
	// Admin 申請詳情；比賣家版多 gov_verify_payload / internal_note / current_approved
	GetProductCertificationApplicationForAdmin(context.Context, *connect.Request[product.GetProductCertificationApplicationForAdminRequest]) (*connect.Response[product.ProductCertificationApplicationAdminResponse], error)
	// Admin 稽核軌跡（append-only review event；自動核准也必須有事件）
	ListProductCertificationAuditLogsForAdmin(context.Context, *connect.Request[product.ListProductCertificationAuditLogsForAdminRequest]) (*connect.Response[product.ListProductCertificationAuditLogsForAdminResponse], error)
	// Admin 核准；同 (product, type) 現行有效那筆會被 SUPERSEDE
	ApproveProductCertificationForAdmin(context.Context, *connect.Request[product.ReviewProductCertificationForAdminRequest]) (*connect.Response[product.ProductCertificationApplicationAdminResponse], error)
	// Admin 駁回（reason_code 必填，缺 → 3028）
	RejectProductCertificationForAdmin(context.Context, *connect.Request[product.ReviewProductCertificationForAdminRequest]) (*connect.Response[product.ProductCertificationApplicationAdminResponse], error)
	// Admin 撤銷已核准（reason_code 必填）；撤銷後投影必須重算
	RevokeProductCertificationForAdmin(context.Context, *connect.Request[product.ReviewProductCertificationForAdminRequest]) (*connect.Response[product.ProductCertificationApplicationAdminResponse], error)
	// Admin 重新查驗：有副作用（消耗政府 API 配額 + 寫 DB）故走 POST。
	// 只更新 gov_verify_state / gov_verify_payload / gov_verified_at，**不改 status、不自動核准**（§9.3）
	ReverifyProductCertificationForAdmin(context.Context, *connect.Request[product.ReverifyProductCertificationForAdminRequest]) (*connect.Response[product.ProductCertificationApplicationAdminResponse], error)
	// 取分類底下所有商品（含分頁，依層級判斷查 category / category_lv2 / category_lv1）
	ListProductsByCategoryForAdmin(context.Context, *connect.Request[product.ListProductsByCategoryForAdminRequest]) (*connect.Response[product.ListProductsByCategoryForAdminResponse], error)
	// 批次更換商品分類，限 L3→L3。**強制連動更新 product.category / category_lv2 / category_lv1 三欄位**。
	// 兩種輸入模式（擇一）：(productIds + targetCategoryId) 或 (sourceCategoryId + targetCategoryId)
	BatchChangeProductCategoryForAdmin(context.Context, *connect.Request[product.BatchChangeProductCategoryForAdminRequest]) (*connect.Response[product.BatchChangeProductCategoryForAdminResponse], error)
	// Hashtag 自動補全（PREFIX/CONTAIN 兩種模式，僅回 product_count > 0，依熱門排序）
	SearchHashtags(context.Context, *connect.Request[product.SearchHashtagsRequest]) (*connect.Response[product.SearchHashtagsResponse], error)
	// 日期區間熱門 hashtag 查詢，依區間內 distinct ACTIVE 商品數降冪
	GetPopularHashtags(context.Context, *connect.Request[product.GetPopularHashtagsRequest]) (*connect.Response[product.GetPopularHashtagsResponse], error)
	// 公開商品產地聚合：依 ACTIVE 商品 group by origin 回傳產地與商品數列表
	GetPublicOriginsSummary(context.Context, *connect.Request[product.GetPublicOriginsSummaryRequest]) (*connect.Response[product.GetPublicOriginsSummaryResponse], error)
	// 商家註冊所在地完整聚合；固定回 22 縣市，count 與列表 filter 共用 seller SSOT。
	GetPublicSellerCitiesSummary(context.Context, *connect.Request[product.GetPublicSellerCitiesSummaryRequest]) (*connect.Response[product.GetPublicSellerCitiesSummaryResponse], error)
	// 回傳「至少有一件公開上架商品」的 store_id 全集。
	// 內部 RPC（seller-service 推薦賣家 / marketplace rail 用來濾掉空店），不對前端暴露。
	// 詳見 02 §5.13c
	ListStoreIDsWithPublicProductsInternal(context.Context, *connect.Request[product.ListStoreIDsWithPublicProductsInternalRequest]) (*connect.Response[product.ListStoreIDsWithPublicProductsInternalResponse], error)
	// 驗證 category_id 為合法葉節點，回傳 cat_l1/l2 反正規化欄位
	// 內部 RPC（x-internal-service 免身份驗證），不對前端暴露
	// 詳見 02 §9.1
	ValidateLeafCategoryInternal(context.Context, *connect.Request[product.ValidateLeafCategoryInternalRequest]) (*connect.Response[product.ValidateLeafCategoryInternalResponse], error)
	// 由 Product Import Service 在 commit 階段呼叫，將暫存 import_item 轉正為 product + product_sku
	// 內部 RPC，與 CreateProduct 分離以維持權限邊界與審計線索清晰
	// 詳見 02 §9.2
	CreateProductFromImportInternal(context.Context, *connect.Request[product.CreateProductFromImportInternalRequest]) (*connect.Response[product.CreateProductFromImportInternalResponse], error)
	// 批次偵測商品名稱是否與賣家既有商品重複（CSV 解析 + UpdateImportItem 時呼叫）
	// 內部 RPC
	// 詳見 02 §9.5
	BatchCheckSellerProductNames(context.Context, *connect.Request[product.BatchCheckSellerProductNamesRequest]) (*connect.Response[product.BatchCheckSellerProductNamesResponse], error)
	// 商品上架完整檢核（雙時機點 validator）；csv 路徑不能繞過任何上架規則
	// 內部 RPC；由 ProductPublishValidator 執行
	// 詳見 40 號設計書 §4.3a
	ValidateProductDraft(context.Context, *connect.Request[product.ValidateProductDraftRequest]) (*connect.Response[product.ValidateProductDraftResponse], error)
	// batch 查多個 product 的 (id, name, status, status_label) 用於 import 端 hydrate
	// 內部 RPC
	// 詳見 40 號設計書 §4.3b
	GetProductsBriefInternal(context.Context, *connect.Request[product.GetProductsBriefInternalRequest]) (*connect.Response[product.GetProductsBriefInternalResponse], error)
}

